"""A hidden Markov model part-of-speech tagger with Viterbi decoding, on the Penn Treebank sample.

First, once:  python -c "import nltk; [nltk.download(r) for r in ('treebank', 'universal_tagset')]"
"""

import math
from collections import Counter, defaultdict

import numpy as np
from nltk.corpus import treebank
from nltk.tag.mapping import map_tag

START, END = "<s>", "</s>"


def load():
    """Tagged sentences with universal tags, without the treebank's empty elements (tag -NONE-)."""
    sents = [[(w, map_tag("en-ptb", "universal", t)) for w, t in s if t != "-NONE-"]
             for s in treebank.tagged_sents()]
    return sents[:3000], sents[3000:]


def shape(word):
    """A pseudo-word for words seen at most once: it keeps clues to the tag, such as a suffix or a capital."""
    if any(c.isdigit() for c in word):
        return "<NUM>"
    if "-" in word:
        return "<HYPHEN>"
    for suffix in ("ing", "ed", "ly", "ion", "s"):
        if word.lower().endswith(suffix):
            return f"<-{suffix}>"
    if word[0].isupper():
        return "<CAP>"
    return "<UNK>"


class HMMTagger:
    def __init__(self, k=0.1):
        self.k = k  # add-k smoothing for transitions and emissions

    def fit(self, sents):
        freq = Counter(w for s in sents for w, _ in s)
        self.known = {w for w, c in freq.items() if c > 1}  # hapaxes become shape classes, to learn unknown words
        self.tags = sorted({t for s in sents for _, t in s})
        trans, emit = Counter(), defaultdict(Counter)
        for s in sents:
            tags = [START] + [t for _, t in s] + [END]
            trans.update(zip(tags, tags[1:]))
            for w, t in s:
                emit[t][self.word(w)] += 1
        self.vocab = sorted({w for t in emit for w in emit[t]})
        n, v = len(self.tags), len(self.vocab)
        index = {t: i for i, t in enumerate(self.tags)}
        self.windex = {w: i for i, w in enumerate(self.vocab)}
        a = np.full((n + 1, n + 1), self.k)  # rows: previous tag (last row is START); columns: tag (last is END)
        for (prev, t), c in trans.items():
            a[n if prev == START else index[prev], n if t == END else index[t]] += c
        a[:n + 1, :] /= a.sum(axis=1, keepdims=True)
        b = np.full((n, v), self.k)
        for t in emit:
            for w, c in emit[t].items():
                b[index[t], self.windex[w]] += c
        b /= b.sum(axis=1, keepdims=True)
        self.log_a, self.log_b = np.log(a), np.log(b)
        return self

    def word(self, w):
        return w if w in self.known else shape(w)

    def viterbi(self, words):
        n, T = len(self.tags), len(words)
        obs = [self.windex.get(self.word(w), self.windex.get("<UNK>")) for w in words]
        v = np.zeros((T, n))
        back = np.zeros((T, n), dtype=int)
        # TODO: fill v (best log probability of any path ending in each tag) and back (the previous tag on it):
        #   v[0] = log P(tag | START) + log P(word 0 | tag)          -> self.log_a[n, :n] + self.log_b[:, obs[0]]
        #   v[i][t] = max over prev of (v[i-1][prev] + log P(t | prev)) + log P(word i | t)
        #             (self.log_a[:n, :n][prev, t]; NumPy: scores = v[i - 1][:, None] + self.log_a[:n, :n])
        #   back[i][t] = the argmax prev
        # Then add log P(END | tag), self.log_a[:n, n], to v[-1], take the best last tag and follow back to the start.
        return ["NOUN"] * T


def evaluate(tagger, train, test):
    seen = {w for s in train for w, _ in s}
    right = Counter()
    total = Counter()
    errors = Counter()
    for s in test:
        words = [w for w, _ in s]
        for (w, gold), pred in zip(s, tagger.viterbi(words)):
            kind = "known" if w in seen else "unknown"
            total[kind] += 1
            right[kind] += gold == pred
            if gold != pred:
                errors[(gold, pred)] += 1
    acc = (right["known"] + right["unknown"]) / (total["known"] + total["unknown"])
    return acc, right, total, errors


def baseline(train, test):
    """Each word's most frequent training tag; NOUN for unknown words."""
    best = {}
    by_word = defaultdict(Counter)
    for s in train:
        for w, t in s:
            by_word[w][t] += 1
    for w, c in by_word.items():
        best[w] = c.most_common(1)[0][0]
    pairs = [(t, best.get(w, "NOUN")) for s in test for w, t in s]
    return sum(g == p for g, p in pairs) / len(pairs)


def main():
    train, test = load()
    print(f"Train {len(train)} sentences ({sum(map(len, train))} tokens), test {len(test)} ({sum(map(len, test))} tokens)")
    tagger = HMMTagger().fit(train)
    print(f"{len(tagger.tags)} tags: {' '.join(tagger.tags)}")
    print(f"P(NOUN | DET) = {math.exp(tagger.log_a[tagger.tags.index('DET'), tagger.tags.index('NOUN')]):.3f}, "
          f"P(VERB | DET) = {math.exp(tagger.log_a[tagger.tags.index('DET'), tagger.tags.index('VERB')]):.3f}")
    for sentence in ["Investors snapped up shares of Glorbex yesterday .", "The old man the boats ."]:
        words = sentence.split()
        print("Tagged:", " ".join(f"{w}/{t}" for w, t in zip(words, tagger.viterbi(words))))
    print(f"Most-frequent-tag baseline: {baseline(train, test):.4f}")
    acc, right, total, errors = evaluate(tagger, train, test)
    print(f"HMM accuracy {acc:.4f}: known words {right['known'] / total['known']:.4f}, "
          f"unknown words {right['unknown'] / total['unknown']:.4f} ({total['unknown']} unknown tokens)")
    print("Commonest errors (gold, predicted):", errors.most_common(4))


if __name__ == "__main__":
    main()

"""A small search engine: an inverted index, Boolean queries, TF-IDF and BM25 ranking, and evaluation.

Needs only NLTK itself (for the Porter stemmer); no data downloads.
"""

import math
import re
from collections import Counter, defaultdict

from nltk.stem import PorterStemmer

STOP = {"a", "an", "and", "are", "at", "by", "for", "from", "in", "is", "it", "of", "on", "or", "the", "to", "you"}
STEM = PorterStemmer().stem


def analyse(text):
    """The same steps for documents and queries: lowercase, words only, drop stop words, stem."""
    return [STEM(w) for w in re.findall(r"[a-z]+", text.lower()) if w not in STOP]


def load(docs_path="docs.tsv", queries_path="queries.tsv"):
    docs = dict(line.rstrip("\n").split("\t") for line in open(docs_path, encoding="utf-8"))
    queries = []
    for line in open(queries_path, encoding="utf-8"):
        qid, text, relevant = line.rstrip("\n").split("\t")
        queries.append((qid, text, set(relevant.split())))
    return docs, queries


class Index:
    def __init__(self, docs):
        self.postings = defaultdict(list)  # term -> [(doc_id, tf)] in doc_id order
        self.length = {}
        for doc_id in sorted(docs):
            terms = analyse(docs[doc_id])
            self.length[doc_id] = len(terms)
            for term, tf in sorted(Counter(terms).items()):
                self.postings[term].append((doc_id, tf))
        self.n = len(docs)
        self.avgdl = sum(self.length.values()) / self.n

    def docs_with(self, term):
        return [d for d, _ in self.postings.get(term, [])]

    def boolean_and(self, query):
        """Intersect the postings lists, rarest term first, by walking two sorted lists in step."""
        lists = sorted((self.docs_with(t) for t in set(analyse(query))), key=len)
        result = lists[0] if lists else []
        # TODO 1: for each other list, walk it and result together with two positions i and j: keep a doc id when
        #         both lists have it, otherwise move on in whichever list has the smaller id. Don't use set().
        return result

    def idf(self, term):
        return math.log10(self.n / len(self.postings[term]))

    def tfidf(self, query):
        """Cosine similarity of log-tf x idf vectors (documents normalised by their own vector length)."""
        q = Counter(t for t in analyse(query) if t in self.postings)
        q_vec = {t: (1 + math.log10(tf)) * self.idf(t) for t, tf in q.items()}
        scores, norms = defaultdict(float), defaultdict(float)
        for term, plist in self.postings.items():
            for doc_id, tf in plist:
                w = (1 + math.log10(tf)) * self.idf(term)
                norms[doc_id] += w * w
                if term in q_vec:
                    scores[doc_id] += w * q_vec[term]
        q_norm = math.sqrt(sum(w * w for w in q_vec.values())) or 1.0
        return rank({d: s / (math.sqrt(norms[d]) * q_norm) for d, s in scores.items()})

    def bm25(self, query, k1=1.2, b=0.75):
        scores = defaultdict(float)
        # TODO 2: for each query term in the index, idf = ln(1 + (N - df + 0.5) / (df + 0.5)), and for each
        #         (doc_id, tf) in its postings add idf * tf * (k1 + 1) / (tf + k1 * (1 - b + b * dl / avgdl))
        return rank(scores)


def rank(scores):
    return sorted(scores, key=lambda d: (-scores[d], d))  # ties broken by doc id, so runs are repeatable


def precision_at(ranking, relevant, k):
    return sum(d in relevant for d in ranking[:k]) / k


def average_precision(ranking, relevant):
    # TODO 3: the mean, over the relevant documents, of the precision at the rank where each is found
    #         (a relevant document that is never retrieved adds 0)
    return 0.0


def main():
    docs, queries = load()
    index = Index(docs)
    print(f"{index.n} documents, {len(index.postings)} terms, average length {index.avgdl:.2f} terms")
    print("Postings for 'ferri':", index.postings["ferri"])
    print(f"idf(ferri) = {index.idf('ferri'):.3f}, idf(swim) = {index.idf('swim'):.3f}")

    found = index.boolean_and("swimming lessons")
    relevant = queries[5][2]
    tp = len(set(found) & relevant)
    p, r = tp / len(found), tp / len(relevant)
    print(f"Boolean 'swimming AND lessons': {found}; precision {p:.2f}, recall {r:.2f}, F1 {2 * p * r / (p + r):.2f}")

    totals = Counter()
    for qid, text, relevant in queries:
        line = [f"{qid} {text!r}"]
        for name in ("tfidf", "bm25"):
            ranking = getattr(index, name)(text)
            ap = average_precision(ranking, relevant)
            totals[name] += ap
            line.append(f"{name} top 3 {ranking[:3]} P@3 {precision_at(ranking, relevant, 3):.2f} AP {ap:.2f}")
        print("\n  ".join(line))
    for name in ("tfidf", "bm25"):
        print(f"MAP {name}: {totals[name] / len(queries):.3f}")


if __name__ == "__main__":
    main()
